"""Read-only chronology/binding gate for a separate prospective RPI GLM branch.

This consumes owner-verified exports of existing Campaign/isolated-executor
records. It neither imports evidence, runs code, authenticates a laboratory,
assigns reward, nor creates a new campaign. Hashes prove bindings, not truth.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import sqlite3
from datetime import datetime
from pathlib import Path

from .contracts import canonical, check_physical_forecast_source, digest
from .evaluation import (
    measurement_definition_check,
    measurement_stage_check,
    quality_review_exclusion,
)

SCHEMA = "rpi-prospective-glm-v1"
STAGES = {"as_sintered", "after_first_anneal", "after_second_anneal"}
SOURCE_KINDS = {"reviewed_rpi_record", "accepted_protocol", "public_literature",
                "attributed_specialist_interpretation"}
EXCLUDED_INPUTS = {"astra_history", "astra_models_or_answers", "evaluator_internals",
                   "unreleased_outcomes", "synthetic_measurements"}
ASSESSMENT_CONTRACT = {
    "schema": "rpi-forecast-diagnostics-v1",
    "point_errors": ["prediction_minus_observation", "absolute_error"],
    "units": "each_committed_endpoint_unit",
    "uncertainty": "no_proper_score_without_predeclared_distribution_and_scoring_rule",
    "abstention": "no_numeric_error_retained_in_total_target_coverage",
    "missing_outcome": "unavailable_not_failure_retained_in_total_target_coverage",
    "commitment_selection": "all_native_prospective_decisions_no_best_of",
    "physical_acceptance_threshold": None,
}

# An attributed owner import prerequisite, never an investigator solution. The
# existing native store requires a model-bound request before physical receipt.
INITIALIZATION_SOURCE = '''def forecast(payload):
    return {"initialization_only": True, "policy_forecast": False, "predictions": [
        {"specimen_id": s["specimen_id"], **{
            q: {"mean": None, "sd": None, "unit": unit, "status": "unsupported",
                "reason": "Owner initialization of previously accepted physical records; no policy prediction"}
            for q, unit in (("density_g_cm3", "g/cm^3"), ("grain_size_nm", "nm"))}}
        for s in payload["request"]["specimens"]]}
'''


def seed_public_branch(destination, packet, files, *, allow_fixture=False):
    """Owner-only fresh branch via native Campaign APIs, no inference or lab action.

`packet` is an explicit semantic allowlist reviewed by the owner, not a Campaign
directory. `files` maps SHA256s to original paths. Only hashes referenced by the
selected, already released deliveries are copied. A partial failure leaves a
labeled nonadmitted fresh directory for inspection; it never retries or cleans up.
The caller must keep the private receipt outside the investigator sources.
"""
    from .operator import Campaign

    allowed = {"schema", "fixture_only", "branch_id", "reviewer", "input_review",
               "sources", "requests", "deliveries", "preserved_state_manifest_sha256"}
    if set(packet) - allowed or packet.get("schema") != "rpi-public-branch-seed-v1":
        raise ValueError("unknown seed fields or schema; no whole-state copy is allowed")
    if packet.get("fixture_only") and not allow_fixture:
        raise ValueError("fixture requires explicit opt-in")
    if not packet.get("reviewer") or not packet.get("deliveries"):
        raise ValueError("reviewer and at least one already released delivery required")
    review = packet["input_review"]
    if not review.get("reviewer") or set(review["excluded_categories"]) != EXCLUDED_INPUTS:
        raise ValueError("owner input-exclusion review required")
    _time(review["reviewed_at"])
    for source in packet["sources"]:
        if source["kind"] not in SOURCE_KINDS or digest(source["content"]) != source["sha256"]:
            raise ValueError("unreviewed source category or changed source content")
    requests = {r["request_id"]: r for r in packet["requests"]}
    if len(requests) != len(packet["requests"]):
        raise ValueError("duplicate initialization request")
    needed = set()
    for record in packet["requests"]:
        if set(record) != {"request_id", "request", "acceptance_source"}:
            raise ValueError("request allowlist excludes old forecasts and model bindings")
        if record["request"]["origin"] != "physical":
            raise ValueError("initialization request must be physical")
        if not packet.get("fixture_only") and record["request"].get("fixture_only"):
            raise ValueError("fixture request cannot seed physical investigation")
        acceptance = record["acceptance_source"]
        if not acceptance.get("reviewer") or len(acceptance["sha256"]) != 64:
            raise ValueError("accepted protocol source review required")
        _time(acceptance["reviewed_at"])
    delivery_ids = [item["delivery"]["delivery_id"] for item in packet["deliveries"]]
    if len(delivery_ids) != len(set(delivery_ids)):
        raise ValueError("duplicate initialization delivery")
    for item in packet["deliveries"]:
        delivery, release = item["delivery"], item["source_release"]
        if (set(item) != {"delivery", "source_release"}
                or delivery["request_id"] not in requests
                or delivery["origin"] != "physical"
                or release["delivery_id"] != delivery["delivery_id"]
                or release["delivery_sha256"] != digest(delivery)
                or not release.get("reviewer")):
            raise ValueError("delivery lacks matching original owner release")
        if _time(delivery["received_at"]) > _time(release["released_at"]):
            raise ValueError("invalid source receipt/release chronology")
        if _time(release["released_at"]) > _time(review["reviewed_at"]):
            raise ValueError("packet review predates source release")
        if delivery.get("corrects_delivery_id") and delivery["corrects_delivery_id"] not in delivery_ids:
            raise ValueError("selected correction requires its original delivery and release")
        if not packet.get("fixture_only") and (delivery.get("fixture_only") or any(
            r.get("fixture_only") or r.get("rehearsal") for r in delivery["observations"]
        )):
            raise ValueError("fixture delivery cannot seed physical investigation")
        for name, blob in delivery["raw_files"].items():
            if Path(name).name != name:
                raise ValueError("original logical names must be basenames")
            path = Path(files[blob["sha256"]])
            if hashlib.sha256(path.read_bytes()).hexdigest() != blob["sha256"]:
                raise ValueError("original file hash mismatch")
            needed.add(blob["sha256"])
    destination = Path(destination).resolve()
    destination.mkdir(parents=False, exist_ok=False, mode=0o700)
    packet_hash = digest(packet)
    (destination / "SEED_PACKET.json").write_text(canonical(packet) + "\n")
    with Campaign.open(destination / "campaign", {
        "campaign_id": packet["branch_id"], "execution_mode": "physical",
        "fixture_only": packet.get("fixture_only", False),
        "initialization_packet_sha256": packet_hash,
        "initialization_role": "public_evidence_replay_not_new_manufacture",
    }) as campaign:
        campaign.adopt_model(INITIALIZATION_SOURCE,
                             "Owner all-abstention import prerequisite; no Astra source or policy forecast",
                             [], call_id="public-seed-model")
        submitted = set()

        def submit_initialization_request(rid):
            if rid in submitted:
                return
            record = requests[rid]
            # Execute only the fixed owner-authored initializer above, never any
            # supplied source or investigator code.
            namespace = {}
            exec(INITIALIZATION_SOURCE, namespace)  # noqa: S102
            request = record["request"]
            prediction = namespace["forecast"]({"request": request})
            campaign.submit(request, prediction, rid, call_id="public-seed-request:" + rid)
            campaign.accept(rid, packet["reviewer"],
                            "Replay of already accepted physical records; not new RPI approval: "
                            + canonical(record["acceptance_source"]),
                            call_id="public-seed-acceptance:" + rid)
            submitted.add(rid)

        # Replay original review chronology. An existing-body operation requires
        # its preceding manufacture/stage receipt to have been released, so all
        # requests cannot be submitted before any of the reviewed deliveries.
        ordered_deliveries = sorted(packet["deliveries"],
                                    key=lambda item: _time(item["source_release"]["released_at"]))
        for item in ordered_deliveries:
            original, release = item["delivery"], item["source_release"]
            submit_initialization_request(original["request_id"])
            delivery = json.loads(canonical(original))
            delivery["source_receipt_provenance"] = {
                "delivery_sha256": digest(original), "release_sha256": digest(release),
                "owner_received_at": original["received_at"],
                "owner_released_at": release["released_at"],
                "reviewer": release["reviewer"], "branch_import_is_not_new_measurement": True}
            for row in delivery["observations"]:
                row["owner_received_at"] = original["received_at"]
                row["owner_released_at"] = release["released_at"]
            rid, did = original["request_id"], original["delivery_id"]
            campaign.receive(rid, delivery, {name: Path(files[blob["sha256"]])
                for name, blob in original["raw_files"].items()}, call_id="public-seed-receive:" + did)
            campaign.release(did, packet["reviewer"], call_id="public-seed-release:" + did)
        # Preserve selected accepted requests with no returned records as plans.
        # The same native preconditions apply; an unavailable body/stage is not
        # manufactured or inferred merely to make an initialization succeed.
        for rid in requests:
            submit_initialization_request(rid)
        verification = campaign.verify()
        evidence = campaign.evidence()
        receipt = {"schema": "rpi-public-branch-seed-receipt-v1", "status": "seeded_not_launched",
                   "fixture_only": packet.get("fixture_only", False),
                   "packet_sha256": packet_hash, "branch_id": packet["branch_id"],
                   "evidence_sha256": digest(evidence), "evidence_ids": _ids(evidence),
                   "model_count": len(campaign.models()), "policy_calls": 0,
                   "model_role": "owner_all_abstention_import_prerequisite",
                   "copied_raw_hashes": sorted(needed), "copied_astra_models": 0,
                   "copied_astra_history": 0, "training_admission": False,
                   "source_release_replay_order": [item["delivery"]["delivery_id"]
                                                   for item in ordered_deliveries],
                   "physical_execution_authority": "not_granted", "verification": verification}
        (destination / "INITIAL_EVIDENCE.json").write_text(canonical(evidence) + "\n")
    public_sources = {"branch_initialization": {
        "role": "first_reviewed_physical_packet_initialization_not_a_prediction_test",
        "packet_sha256": packet_hash, "historical_policy": "gpt-6-astra preserved separately",
        "initial_model_role": receipt["model_role"], "owner": packet["reviewer"],
        "source_receipts": [d["source_release"] for d in packet["deliveries"]]},
        "reviewed_public_sources": packet["sources"]}
    (destination / "SOURCE_PACKET.json").write_text(canonical(public_sources) + "\n")
    (destination / "SEED_RECEIPT.json").write_text(canonical(receipt) + "\n")
    return receipt


def _time(value):
    stamp = datetime.fromisoformat(value)
    if stamp.tzinfo is None:
        raise ValueError("timezone required")
    return stamp


def _ids(rows):
    ids = [row["evidence_id"] for row in rows]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate evidence identity")
    return ids


def _target(row):
    return row["specimen_id"], row["measurement_stage"], row["quantity"]


def commitment_binding(branch, evidence, forecast, source, executions):
    """JSON rationale for the existing append-only record_decision tool.

Freeze this exact value in the native decision before any later outcome receipt.
The forecast may concern a later stage on an existing body; no manufacture is
requested and no new specimen identity is fabricated.
"""
    return {"schema": SCHEMA, "branch_sha256": digest(branch),
            "evidence_sha256": digest(evidence), "forecast_sha256": digest(forecast),
            "assessment_contract_sha256": digest(forecast["assessment_contract"]),
            "source_sha256": hashlib.sha256(source.encode()).hexdigest(),
            "executions_sha256": digest(executions)}


def validate(bundle, *, allow_fixture=False):
    """Validate integrity and chronology; return per-target outcome eligibility.

Caller must verify the exported records against native stores/receipts. A valid
result is not a numerical score, physical validation, leakage proof, or training
admission. Fixtures require explicit opt-in and can never become physical scores.
"""
    issues = []
    outcomes = []
    fixture = bundle.get("fixture_only") is True
    result = {"schema": SCHEMA, "fixture_only": fixture, "issues": issues,
              "outcomes": outcomes, "physical_score_admissible": False,
              "training_admission": False, "numerical_score": None,
              "scope": "owner-export binding and chronology only"}

    def require(condition, issue):
        if not condition:
            issues.append(issue)

    try:
        canonical(bundle)  # Reject nonfinite values anywhere, including extensions.
        require(bundle["schema"] == SCHEMA, "schema_mismatch")
        require(not fixture or allow_fixture, "fixture_requires_explicit_opt_in")
        branch, evidence = bundle["branch"], bundle["evidence"]
        initial = bundle["initial_evidence"]
        require(bool(initial), "initial_reviewed_packet_required")
        initial_ids, evidence_ids = _ids(initial), _ids(evidence)
        require(branch["initial_evidence_sha256"] == digest(initial), "initial_snapshot_mismatch")
        require(branch["initial_evidence_ids"] == initial_ids, "initial_identity_mismatch")
        require(bool(branch["branch_id"]), "branch_identity_missing")
        require(branch["preserved_investigator"] == "gpt-6-astra", "historical_identity_missing")
        preserved = branch["preserved_state_manifest_sha256"]
        require(len(preserved) == 64 and all(c in "0123456789abcdef" for c in preserved),
                "preserved_state_manifest_missing")
        policy = branch["policy"]
        require(policy["model_family"] == "GLM-5.3-Flash", "wrong_policy_family")
        for field in ("checkpoint_id", "checkpoint_revision", "precision", "provider",
                      "runtime_receipt_sha256"):
            require(isinstance(policy[field], str) and bool(policy[field].strip()),
                    "missing_policy_" + field)
        revision = policy["checkpoint_revision"]
        require(len(revision) in {40, 64} and all(c in "0123456789abcdef" for c in revision),
                "checkpoint_revision_not_pinned")
        runtime = bundle["policy_runtime_receipt"]
        require(digest(runtime) == policy["runtime_receipt_sha256"], "runtime_receipt_hash_mismatch")
        require(all(runtime.get(key) == policy[key] for key in (
            "model_family", "checkpoint_id", "checkpoint_revision", "precision", "provider")),
            "policy_runtime_identity_mismatch")
        require(isinstance(branch["assistance"], list), "assistance_attribution_missing")
        review = branch["input_review"]
        require(bool(review["reviewer"]), "input_review_missing")
        require(set(review["excluded_categories"]) == EXCLUDED_INPUTS, "input_exclusions_incomplete")
        require(bool(branch["public_sources"]), "source_allowlist_empty")
        for item in branch["public_sources"]:
            require(item["kind"] in SOURCE_KINDS, "disallowed_initial_source_category")
            sha = item["sha256"]
            require(len(sha) == 64 and all(c in "0123456789abcdef" for c in sha),
                    "invalid_public_source_hash")
        started = _time(branch["started_at"])
        require(_time(review["reviewed_at"]) <= started, "input_review_after_start")
        for row in initial:
            require(row["origin"] == "physical", "nonphysical_initial_evidence")
            require(_time(row["received_at"]) <= _time(row["released_at"]) <= started,
                    "initialization_before_reviewed_release")
        decision, forecast = bundle["decision"], bundle["forecast"]
        require(forecast["assessment_contract"] == ASSESSMENT_CONTRACT,
                "unknown_or_changed_assessment_contract")
        committed = _time(decision["recorded_at"])
        require(started <= committed, "commitment_before_policy_start")
        require(decision["decision"] == "prospective_prediction", "wrong_decision_record")
        require(decision["evidence_ids"] == evidence_ids, "decision_evidence_ids_mismatch")
        require(decision["evidence_sha256"] == digest(evidence), "decision_evidence_hash_mismatch")
        require(set(initial_ids) <= set(evidence_ids), "initial_packet_missing_from_cutoff")
        current_by_id = {row["evidence_id"]: row for row in evidence}
        for row in initial:
            # A later released correction can mark a row superseded; it cannot
            # silently rewrite its original values, identities or timestamps.
            original = {k: v for k, v in row.items() if k != "superseded"}
            current = {k: v for k, v in current_by_id.get(row["evidence_id"], {}).items()
                       if k != "superseded"}
            require(original == current, "initial_evidence_content_changed")
        releases = {r["delivery_id"]: r for r in bundle["releases"]}
        for row in evidence:
            require(row["origin"] == "physical", "nonphysical_cutoff_evidence")
            require(fixture or not (row.get("fixture_only") or row.get("rehearsal")),
                    "rehearsal_evidence_in_physical_branch")
            require(_time(row["received_at"]) <= _time(row["released_at"]) <= committed,
                    "cutoff_contains_later_evidence")
            release = releases[row["delivery_id"]]
            require(bool(release["reviewer"]) and release["released_at"] == row["released_at"],
                    "cutoff_release_receipt_mismatch")
        source, executions = bundle["source"], bundle["executions"]
        expected = commitment_binding(branch, evidence, forecast, source, executions)
        require(json.loads(decision["rationale"]) == expected, "immutable_decision_binding_mismatch")
        require(bool(executions) and len({e["execution_id"] for e in executions}) == len(executions),
                "distinct_original_execution_receipts_required")
        for execution in executions:
            require(execution["status"] == "ok", "execution_did_not_complete")
            require(execution["hashes"]["executed_source_sha256"] == expected["source_sha256"],
                    "executed_source_mismatch")
            require(execution["result"] == forecast, "executed_forecast_mismatch")
            # Original input text is retained because executor encoding is not
            # assumed to equal the Campaign canonical JSON encoding.
            text = execution["input_text"]
            require(hashlib.sha256(text.encode()).hexdigest() == execution["hashes"]["input_sha256"],
                    "execution_input_hash_mismatch")
            require(json.loads(text)["evidence"] == evidence, "execution_cutoff_mismatch")
        if len(executions) == 2:
            require(executions[0]["hashes"]["input_sha256"] ==
                    executions[1]["hashes"]["input_sha256"], "replay_input_mismatch")
        check_physical_forecast_source(expected["source_sha256"], {"origin": "physical"}, forecast)
        targets = forecast["targets"]
        require(bool(targets), "no_committed_targets")
        by_target = {}
        for target in targets:
            key = _target(target)
            require(key not in by_target, "duplicate_committed_target")
            by_target[key] = target
            require(bool(key[0]) and bool(key[2]) and key[1] in STAGES, "ambiguous_target_identity")
            require(bool(target["unit"]), "missing_target_unit")
            require(isinstance(target["processing_coordinates"], dict)
                    and bool(target["processing_coordinates"]), "missing_processing_coordinates")
            require(target["coordinate_basis"] in {"requested", "delivered"},
                    "coordinate_basis_unspecified")
            context = target["measurement_context"]
            require(all(context.get(k) for k in ("method", "measurement_population",
                    "measurement_statistic", "statistical_unit")), "measurement_definition_incomplete")
            mean, sd = target["mean"], target["sd"]
            if mean is None:
                require(target["status"] in {"unsupported", "unavailable", "abstained"}
                        and sd is None and bool(target.get("reason")), "invalid_abstention")
            else:
                require(type(mean) in (float, int) and math.isfinite(mean), "invalid_prediction")
                require(target["status"] == "predicted", "numeric_prediction_status_mismatch")
                require(sd is None or type(sd) in (float, int) and math.isfinite(sd) and sd > 0,
                        "unsupported_zero_or_invalid_uncertainty")
                require(sd is not None or bool(target.get("uncertainty_limit")),
                        "unknown_uncertainty_limit_missing")
        rows = bundle.get("later_evidence", [])
        later_ids = _ids(rows)
        require(not set(initial_ids) & set(later_ids), "first_packet_cannot_be_rescored")
        candidates = {}
        for row in rows:
            key = row.get("specimen_id"), row.get("measurement_stage"), row.get("quantity")
            if key in by_target and row["evidence_id"] not in evidence_ids and not row.get("superseded"):
                candidates.setdefault(key, []).append(row["evidence_id"])
        result["ambiguous_targets"] = [
            {**dict(zip(("specimen_id", "measurement_stage", "quantity"), key)),
             "evidence_ids": ids, "reason": "precommitted_reduction_or_identity_required"}
            for key, ids in candidates.items() if len(ids) > 1]
        seen_targets = set()
        for row in rows:
            item = {"evidence_id": row["evidence_id"], "eligible": False}
            outcomes.append(item)
            # A complete physical packet also contains logs, aliquots and
            # unresolved stages. Keep them explicitly unscored; do not require
            # the owner to cherry-pick a forecast-only packet for this gate.
            key = row.get("specimen_id"), row.get("measurement_stage"), row.get("quantity")
            seen_targets.add(key)
            reason = None
            release = releases.get(row["delivery_id"], {})
            if row["evidence_id"] in evidence_ids:
                reason = "outcome_already_in_commitment_cutoff"
            elif row["origin"] != "physical":
                reason = "nonphysical_outcome"
            elif row.get("fixture_only") or row.get("rehearsal") or fixture:
                reason = "fixture_only_never_physical_score"
            elif row.get("superseded"):
                reason = "superseded_outcome"
            elif key not in by_target:
                reason = "uncommitted_specimen_stage_or_endpoint"
            elif len(candidates[key]) > 1:
                reason = "multiple_outcomes_require_precommitted_reduction_or_identity"
            elif _time(row.get("owner_received_at", row["received_at"])) <= committed:
                reason = "owner_received_before_commitment"
            elif _time(row["released_at"]) < _time(row["received_at"]):
                reason = "outcome_release_before_receipt"
            elif (not release.get("reviewer")
                  or release.get("released_at") != row["released_at"]):
                reason = "outcome_release_unreviewed"
            elif (row.get("earliest_known_at") is None
                  or not row.get("knowledge_chronology_reviewer")):
                reason = "outcome_knowledge_chronology_unreviewed"
            elif _time(row["earliest_known_at"]) <= committed:
                reason = "outcome_known_before_commitment"
            else:
                target = by_target[key]
                definition = measurement_definition_check(target, row)
                stage = measurement_stage_check(target, row)
                if stage["status"] != "matched":
                    reason = "measurement_stage_mismatch"
                elif definition["status"] != "matched":
                    reason = "measurement_definition_mismatch_or_unknown"
                elif target["unit"] != row["unit"]:
                    reason = "unit_mismatch_requires_attributed_conversion"
                elif row.get("value") is None:
                    reason = "outcome_unavailable"
                elif row.get("quality_status") in {"invalid", "unresolved", "rejected"}:
                    reason = "outcome_quality_unresolved"
                elif quality_review_exclusion(row) is not None:
                    reason = "outcome_quality_unresolved"
                    item["quality_review_exclusion"] = quality_review_exclusion(row)
                elif target["mean"] is None:
                    reason = "committed_abstention_retained_in_coverage"
                else:
                    item["eligible"] = True
                    item["prospectivity"] = "before_owner_receipt_and_reviewed_knowledge"
                    measured_at = row.get("measured_at")
                    if measured_at is not None:
                        item["prospectivity"] = (
                            "before_reported_measurement" if committed < _time(measured_at)
                            else "measurement_preexisted_commitment_but_was_not_known")
                    item["measurement_time_authenticated"] = False
            item["reason"] = reason
        result["missing_targets"] = [dict(zip(("specimen_id", "measurement_stage", "quantity"), key))
                                     for key in sorted(set(by_target) - seen_targets)]
        result["target_count"] = len(targets)
        result["waiting_for_later_outcomes"] = not bool(rows)
    except (KeyError, TypeError, ValueError, AttributeError, OverflowError) as exc:
        issues.append("malformed_or_unbound_record:" + type(exc).__name__ + ":" + str(exc))
    result["status"] = "rejected" if issues else "fixture_verified" if fixture else "boundary_verified"
    # An invalid global boundary cannot leave a row accidentally score-eligible.
    if issues:
        for row in outcomes:
            row["eligible"] = False
    result["structurally_eligible_outcome_count"] = sum(row["eligible"] for row in outcomes)
    result["native_records_authenticated"] = False
    result["physical_score_admissible"] = False
    result["remaining_assessment"] = [
        "Bind exports to native append-only decision and original execution bytes",
        "Independently replay the committed computation with original inputs",
        "Review original outcome receipts, numerical reductions and scientific applicability",
    ]
    return result


def verify_native_records(bundle, campaign_directory, execution_directories):
    """Read-only owner check against actual native stores and retained file bytes.

No detached boolean or timestamp is treated as authentication. This verifies
the decision's native append-only event/call and source/input/output/transport
files. It is not the separate full isolation audit, independent recalculation,
policy-provider authentication or physical-outcome adjudication.
"""
    directory = Path(campaign_directory).resolve(strict=True)
    database = directory / "campaign.sqlite3"
    bindings = {}

    def file(path):
        path = Path(path)
        if path.is_symlink() or not path.is_file():
            raise ValueError("missing or linked native artifact: " + str(path))
        data = path.read_bytes()
        bindings[str(path)] = hashlib.sha256(data).hexdigest()
        return data

    db = sqlite3.connect(database.as_uri() + "?mode=ro", uri=True)
    db.row_factory = sqlite3.Row
    try:
        from .operator import Campaign
        from .store import Store

        db.execute("BEGIN")  # One consistent read snapshot across concurrent owner releases.
        if db.execute("PRAGMA integrity_check").fetchone()[0] != "ok":
            raise ValueError("native store integrity failure")
        max_event_sequence = db.execute("SELECT MAX(sequence) FROM events").fetchone()[0]
        events = [json.loads(row[0]) for row in db.execute(
            "SELECT data FROM events WHERE kind='decision' ORDER BY sequence")]
        matching = [event for event in events if event["result"] == bundle["decision"]]
        if len(matching) != 1:
            raise ValueError("decision not uniquely present in native append-only history")
        event = matching[0]
        call = db.execute("SELECT result FROM calls WHERE id=?", (event["call_id"],)).fetchone()
        if call is None or json.loads(call[0]) != bundle["decision"]:
            raise ValueError("native call receipt does not match decision")
        # Bypass Store's mutating initializer; all access uses the already-open
        # SQLite mode=ro connection and the existing digest-checking read methods.
        store = object.__new__(Store)
        store.path, store.blobs, store.db = directory, directory / "blobs", db
        campaign = Campaign(store, store.meta("config"))
        if bool(campaign.config.get("fixture_only")) != bool(bundle.get("fixture_only")):
            raise ValueError("fixture attribution differs from native campaign")
        release_rows = {r["delivery_id"]: r for r in store.all("release")}
        for release in bundle["releases"]:
            if release_rows.get(release["delivery_id"]) != release:
                raise ValueError("release export does not match native owner release")
        native_evidence = {row["evidence_id"]: row for row in campaign.evidence()}
        cutoff_ids = set(_ids(bundle["evidence"]))
        for row in bundle["evidence"]:
            actual = native_evidence.get(row["evidence_id"])
            if actual is None or ({k: v for k, v in actual.items() if k != "superseded"}
                                  != {k: v for k, v in row.items() if k != "superseded"}):
                raise ValueError("evidence cutoff does not match original native measurement records")
        # The assessed return is the complete native public remainder at this
        # read. Omitting unfavorable rows, corrections or unrelated measurements
        # is not an authenticated snapshot. This is a current-store check, so a
        # newly released packet requires refreshing the export before assessment.
        later_rows = bundle.get("later_evidence", [])
        later_ids = set(_ids(later_rows))
        expected_later_ids = set(native_evidence) - cutoff_ids
        if later_ids != expected_later_ids:
            raise ValueError("later evidence is not the complete native released remainder")
        for row in later_rows:
            if row != native_evidence[row["evidence_id"]]:
                raise ValueError("later outcome or chronology differs from native measurement record")
        supplied_releases = {r["delivery_id"] for r in bundle["releases"]}
        if len(supplied_releases) != len(bundle["releases"]):
            raise ValueError("duplicate supplied release identity")
        if {row["delivery_id"] for row in native_evidence.values()} != supplied_releases:
            raise ValueError("release export does not cover the complete native evidence snapshot")
    finally:
        db.close()
    originals = {row["execution_id"]: row for row in bundle["executions"]}
    seen = set()
    for supplied in execution_directories:
        root = Path(supplied).resolve(strict=True)
        receipt = json.loads(file(root / "receipt.json"))
        identifier = receipt["execution_id"]
        if identifier not in originals or identifier in seen:
            raise ValueError("unexpected or duplicate native execution directory")
        seen.add(identifier)
        exported = originals[identifier]
        if {k: v for k, v in exported.items() if k != "input_text"} != receipt:
            raise ValueError("execution export differs from original native receipt")
        for name, key in (("input.json", "input_sha256"),
                          ("executed_source.py", "executed_source_sha256"),
                          ("result.json", "result_sha256"),
                          ("runner.py", "runner_sha256"),
                          ("workspace_manifest.json", "workspace_sha256"),
                          ("public_data_bindings.json", "public_data_bindings_sha256")):
            if hashlib.sha256(file(root / name)).hexdigest() != receipt["hashes"][key]:
                raise ValueError("native execution artifact hash mismatch: " + name)
        if file(root / "input.json").decode() != exported["input_text"]:
            raise ValueError("original input bytes differ from exported execution input")
        if file(root / "executed_source.py").decode() != bundle["source"]:
            raise ValueError("original source bytes differ from commitment")
        if json.loads(file(root / "result.json")) != bundle["forecast"]:
            raise ValueError("native result differs from committed forecast")
        transport = json.loads(file(root / "transport_stdout.bin"))
        if (receipt.get("returncode") != 0 or transport.get("status") != "ok"
                or transport.get("result") != bundle["forecast"]):
            raise ValueError("native transport did not return the committed forecast")
    if seen != set(originals):
        raise ValueError("not all original execution directories supplied")
    commitments = [digest(row["result"]) for row in events
                   if row["result"].get("decision") == "prospective_prediction"]
    submitted = digest(bundle["decision"])
    return {"status": "native_commitment_bound", "decision_sha256": submitted,
            "decision_call_id": event["call_id"], "execution_ids": sorted(seen),
            "all_native_prospective_commitment_sha256": commitments,
            "commitment_coverage": {"native_count": len(commitments), "submitted_count": 1,
                "unassessed_commitment_sha256": [sha for sha in commitments if sha != submitted],
                "all_commitments_submitted": len(commitments) == 1},
            "native_outcome_snapshot": {"scope": "all_current_released_rows_outside_cutoff",
                "through_native_event_sequence": max_event_sequence,
                "later_evidence_ids": sorted(later_ids), "later_evidence_sha256": digest(later_rows),
                "outcome_values_and_chronology_bound": True},
            "source_files_sha256": bindings, "fixture_only": bundle.get("fixture_only", False),
            "independent_replay_verified": False, "physical_score_admissible": False,
            "scope": "native decision/release/complete outcome records and retained execution bytes"}


def validate_with_native(bundle, campaign_directory, execution_directories, *, allow_fixture=False):
    """Compose structural checks with native binding; any failure clears eligibility."""
    result = validate(bundle, allow_fixture=allow_fixture)
    try:
        result["native_binding"] = verify_native_records(
            bundle, campaign_directory, execution_directories)
        result["native_records_authenticated"] = True
        result["remaining_assessment"] = result["remaining_assessment"][1:]
    except (ValueError, OSError, KeyError, TypeError, sqlite3.Error) as exc:
        result["issues"].append("native_binding_failed:" + str(exc))
        result["status"] = "rejected"
        result["native_records_authenticated"] = False
    if result["issues"]:
        for row in result["outcomes"]:
            row["eligible"] = False
        result["structurally_eligible_outcome_count"] = 0
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("bundle", type=Path)
    parser.add_argument("--allow-fixture", action="store_true")
    parser.add_argument("--seed-to", type=Path,
                        help="Owner only: create a fresh public branch from an approved seed packet")
    parser.add_argument("--files", type=Path, help="Seed-only JSON map of original SHA256 to path")
    parser.add_argument("--campaign", type=Path, help="Read-only native campaign binding check")
    parser.add_argument("--execution-dir", type=Path, action="append", default=[])
    args = parser.parse_args()
    if args.seed_to is not None:
        if args.files is None:
            parser.error("--seed-to requires --files")
        result = seed_public_branch(args.seed_to, json.loads(args.bundle.read_text()),
                                    json.loads(args.files.read_text()),
                                    allow_fixture=args.allow_fixture)
    else:
        if args.files is not None:
            parser.error("--files requires --seed-to")
        bundle = json.loads(args.bundle.read_text())
        if args.campaign is not None:
            result = validate_with_native(bundle, args.campaign, args.execution_dir,
                                          allow_fixture=args.allow_fixture)
        else:
            result = validate(bundle, allow_fixture=args.allow_fixture)
    print(json.dumps(result, indent=2, allow_nan=False))
    return 1 if result.get("issues") else 0


if __name__ == "__main__":
    raise SystemExit(main())
